function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9а-яё]+/gi, '-')
    .replace(/^-+|-+$/g, '');
}

function seed() {
  const insert = db.prepare(`
    INSERT INTO products (name, slug, brand, model, category, description, price, image, search_text)
    VALUES (@name, @slug, @brand, @model, @category, @description, @price, @image, @search_text)
  `);

  db.exec('BEGIN');
  try {
    db.exec('DELETE FROM products');
    for (const item of demoProducts) {
      const slug = slugify(`${item.model}-${item.name}`);
      const searchText = [item.name, item.brand, item.model, item.category]
        .join(' ')
        .toLowerCase();
      insert.run({
        ...item,
        slug,
        image: item.image || MODEL_IMAGES[item.model] || CATEGORY_IMAGES[item.category] || '/img/product-placeholder.svg',
        search_text: searchText
      });
    }
    db.exec('COMMIT');
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }

  console.log(`Seeded ${demoProducts.length} demo products.`);
}

module.exports = seed;
